void mapcryptunderground_02_function(struct ScreenAttr *screenAttribute, struct CharacterCollection *characterCollection, 
	struct MapInfo *mapInfo, struct ControlTypePool* controlPool, struct CharacterActionCollection *charActionCollection, 
	struct Track *track) {
	BoundingBox jumpinstructions_area = {145, 318, 186, 337, 0, 255};
	BoundingBox dodgeinstructions_area = {141, 380, 405, 489, 0, 255};
	BoundingBox attackinstructions_area = {140, 408, 600, 680, 0, 255};
	
	CharacterAttr *character;
	BoundingBox charBB;
	int i, count;
	for (i = 0; i < characterCollection->currentSize; i++) {
		character = characterCollection->characters[i];
		if (character->type == ALISA) {
			break;
		}
	}
	
	if (character->type != ALISA) {
		return;
	}
	
	character->getBounds(character, &count, &charBB);
	
	if (isOverlap(&charBB, &jumpinstructions_area)) {
		mprinter_printf("You can use enemies as\nstepping stones to reach\nplaces youn normally can't");
	} else if (isOverlap(&charBB, &dodgeinstructions_area)) {
		mprinter_printf("Observe enemy behavior.\nAttack once or twice then\ndash away if you\nfeel danger.Try attacking\nfrom different directions");
	} else if (isOverlap(&charBB, &attackinstructions_area)) {
		mprinter_printf("Some enemies need\na different approach.\nTry hitting the skull\ndemon from the side\nas he attacks");
	}
}

